// Loads enough history to cover BOTH the 13-month default AND the full prior calendar year.
// Default view = last 13 months; dashboard also offers a Prior year preset.
const cfg = $('Config').first().json;
const months = Number(cfg.lookbackMonths) || 13;
const now = new Date();
const pad = n => (n < 10 ? '0' + n : '' + n);
const fmt = dt => dt.getUTCFullYear() + '-' + pad(dt.getUTCMonth() + 1) + '-' + pad(dt.getUTCDate());
const back = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - months, now.getUTCDate()));
const defaultFrom = fmt(back);
const py = now.getUTCFullYear() - 1;
const priorStart = py + '-01-01';
const priorEnd = py + '-12-31';
const loadStart = (defaultFrom < priorStart) ? defaultFrom : priorStart;
const endDay = fmt(now);
return [{ json: { rangeStart: loadStart + 'T00:00:00Z', rangeEnd: endDay + 'T23:59:59Z', startDay: loadStart, endDay: endDay, defaultFrom: defaultFrom, priorStart: priorStart, priorEnd: priorEnd, generatedAt: now.toISOString() } }];

// Outputs one compact record per booking (incl. resource location).
const cfg = $('Config').first().json;
const excludeTypes = String(cfg.excludeBookingTypes || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const includeResTypes = String(cfg.includeResourceTypes || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
function hoursOf(a, b) {
  const s = new Date(String(a) + 'Z').getTime();
  const e = new Date(String(b) + 'Z').getTime();
  if (!isFinite(s) || !isFinite(e) || e <= s) return 0;
  return (e - s) / 3600000;
}
const edges = [];
for (const item of $input.all()) {
  const body = item.json;
  if (body && Array.isArray(body.errors) && body.errors.length) {
    throw new Error('Administrate GraphQL error: ' + JSON.stringify(body.errors));
  }
  const e = body && body.data && body.data.resourceBookings && body.data.resourceBookings.edges;
  if (Array.isArray(e)) edges.push(...e);
}
const out = [];
for (const edge of edges) {
  const n = edge && edge.node;
  if (!n || !n.resource) continue;
  const bType = String(n.bookingType || '').toLowerCase();
  if (excludeTypes.includes(bType)) continue;
  const t = (n.resource.type && n.resource.type.name) || 'Uncategorized';
  if (includeResTypes.length && !includeResTypes.includes(t.toLowerCase())) continue;
  out.push({
    ri: n.resource.id,
    rn: n.resource.name || '(unnamed)',
    rt: t,
    rl: (n.resource.location && n.resource.location.name) || 'No location',
    s: String(n.start).slice(0, 10),
    e: String(n.end).slice(0, 10),
    et: String(n.end).slice(11, 19),
    h: Math.round(hoursOf(n.start, n.end) * 100) / 100
  });
}
if (out.length === 0) return [{ json: { __empty: true } }];
return out.map(json => ({ json }));

// Default view = last 13 months. Presets: Last 13 months / Prior year / Full range. Location column + league, US spelling.
const win = $('Build Window').first().json;
const bookings = $input.all().map(i => i.json).filter(r => !r.__empty);
const loadStart = String(win.startDay || '').slice(0,10);
const endDay = String(win.endDay || '').slice(0,10);
const defaultFrom = String(win.defaultFrom || loadStart).slice(0,10);
const priorStart = String(win.priorStart || '').slice(0,10);
const priorEnd = String(win.priorEnd || '').slice(0,10);
const gen = String(win.generatedAt || '').slice(0,19).replace('T',' ');
const sub = 'Loaded ' + loadStart + ' to ' + endDay + ' (' + bookings.length + ' bookings) | generated ' + gen;
const B = JSON.stringify(bookings);
const html = `<!DOCTYPE html>
<html lang='en'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<title>Resource Utilization</title>
<script src='https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js'></script>
<style>
:root{--p:#6A3CE3;--pd:#4A25A8;--ink:#1c1233;--muted:#6b6580;--bg:#f5f3fb;--card:#fff;--line:#e7e2f5}
*{box-sizing:border-box}
body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
header{background:linear-gradient(120deg,var(--p),var(--pd));color:#fff;padding:20px 24px}
header h1{margin:0;font-size:19px}
header p{margin:4px 0 0;font-size:13px;opacity:.85}
.wrap{max-width:1180px;margin:0 auto;padding:20px 24px 56px}
.bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}
.seg{display:inline-flex;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.seg button{border:0;background:#fff;font:inherit;padding:8px 14px;cursor:pointer;color:var(--ink)}
.seg button.on{background:var(--p);color:#fff}
label{font-size:13px;color:var(--muted)}
select,input[type=date]{font:inherit;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink)}
.btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:8px;padding:8px 12px;font:inherit;cursor:pointer}
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:6px 0 20px}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
.card .k{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.card .v{font-size:26px;font-weight:700;margin-top:6px}
.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:16px}
.panel{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
.panel h2{margin:0 0 12px;font-size:14px}
.chartbox{position:relative;height:270px}
table{width:100%;border-collapse:collapse;font-size:13px}
th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line)}
th{color:var(--muted);cursor:pointer}
td.num,th.num{text-align:right}
.chip{display:inline-block;padding:2px 8px;border-radius:999px;background:#efeaff;color:var(--pd);font-size:12px}
.rankcell{font-weight:700;color:var(--pd)}
#note{margin:8px 0;color:#8a6400;font-size:13px}
@media(max-width:820px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}
</style></head>
<body>
<header><h1>Resource Utilization</h1><p>${sub}</p></header>
<div class='wrap'>
<div class='bar'><label>From</label><input type='date' id='ds' min='${loadStart}' max='${endDay}' value='${defaultFrom}'><label>To</label><input type='date' id='de' min='${loadStart}' max='${endDay}' value='${endDay}'><button id='p13' class='btn'>Last 13 months</button><button id='ppy' class='btn'>Prior year</button><button id='reset' class='btn'>Full range</button><label>Type</label><select id='tf'></select><span style='flex:1'></span><span class='seg' id='seg'><button data-m='d' class='on'>Days</button><button data-m='h'>Hours</button></span></div>
<div id='note'></div>
<div class='cards' id='cards'></div>
<div class='grid'>
<div class='panel'><h2 id='rt'>Top resources</h2><div class='chartbox'><canvas id='rank'></canvas></div></div>
<div class='panel'><h2 id='tt'>By resource type</h2><div class='chartbox'><canvas id='type'></canvas></div></div>
</div>
<div class='panel' style='margin-top:16px'><h2 id='lt'>Locations - most used</h2>
<table id='loc'><thead><tr><th class='num'>#</th><th>Location</th><th class='num'>Days</th><th class='num'>Hours</th><th class='num'>Bookings</th><th class='num'>Resources</th></tr></thead><tbody></tbody></table></div>
<div class='panel' style='margin-top:16px'><h2>All resources</h2>
<table id='tbl'><thead><tr><th data-s='t'>Type</th><th data-s='n'>Resource</th><th data-s='L'>Location</th><th class='num' data-s='d'>Days</th><th class='num' data-s='h'>Hours</th><th class='num' data-s='b'>Bookings</th></tr></thead><tbody></tbody></table>
</div></div>
<script>
var B = ${B};
var LOAD_S='${loadStart}', LOAD_E='${endDay}', DEF_F='${defaultFrom}', PY_S='${priorStart}', PY_E='${priorEnd}';
var from=DEF_F, to=LOAD_E, metric='d', tf='', sk='d', sd=-1, rankC, typeC, ROWS=[];
var PAL=['#6A3CE3','#9B7BEB','#E8A317','#3CB9C4','#E0609B','#6FB57A','#F2784B','#5A6ACF'];
function one(n){return (Math.round(n*10)/10).toLocaleString();}
function inRange(b){return b.s>=from && b.s<=to;}
function daysOf(b){var s=b.s,e=b.e;if(b.et==='00:00:00'&&e>s){var d=new Date(e+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-1);e=d.toISOString().slice(0,10);}var out=[];var cur=new Date(s+'T00:00:00Z');var last=new Date(e+'T00:00:00Z');while(cur<=last){out.push(cur.toISOString().slice(0,10));cur.setUTCDate(cur.getUTCDate()+1);}return out;}
function compute(){var m={};B.forEach(function(b){if(!inRange(b))return;var r=m[b.ri];if(!r){r=m[b.ri]={n:b.rn,t:b.rt,L:b.rl,days:{},h:0,b:0};}r.b+=1;r.h+=b.h;daysOf(b).forEach(function(d){r.days[d]=1;});});ROWS=Object.keys(m).map(function(k){var r=m[k];return {n:r.n,t:r.t,L:r.L,d:Object.keys(r.days).length,h:Math.round(r.h*100)/100,b:r.b};});}
function types(){var s=[];ROWS.forEach(function(r){if(s.indexOf(r.t)<0)s.push(r.t);});return s.sort();}
function view(){return ROWS.filter(function(r){return !tf||r.t===tf;});}
function fillTypes(){var sel=document.getElementById('tf');var keep=tf;sel.innerHTML='<option>All types</option>'+types().map(function(t){return '<option>'+t+'</option>';}).join('');if(types().indexOf(keep)>=0){tf=keep;sel.value=keep;}else{tf='';}}
function cards(){var v=view();var td=v.reduce(function(a,r){return a+r.d;},0);var th=v.reduce(function(a,r){return a+r.h;},0);var c=[['Resources',v.length],['Resource types',types().length],['Total days booked',td.toLocaleString()],['Total hours booked',one(th)]];document.getElementById('cards').innerHTML=c.map(function(x){return '<div class=card><div class=k>'+x[0]+'</div><div class=v>'+x[1]+'</div></div>';}).join('');}
function rank(){var key=metric;var v=view().slice().sort(function(a,b){return b[key]-a[key];}).slice(0,15);document.getElementById('rt').textContent='Top resources by '+(metric==='d'?'days':'hours')+' booked';if(rankC)rankC.destroy();rankC=new Chart(document.getElementById('rank'),{type:'bar',data:{labels:v.map(function(r){return r.n;}),datasets:[{data:v.map(function(r){return r[key];}),backgroundColor:'#6A3CE3',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',plugins:{legend:{display:false}},scales:{y:{ticks:{font:{size:11}}}}}});}
function typeChart(){var key=metric;var v=view();var ts=types();var vals=ts.map(function(t){return v.filter(function(r){return r.t===t;}).reduce(function(a,r){return a+r[key];},0);});document.getElementById('tt').textContent='By resource type ('+(metric==='d'?'days':'hours')+')';if(typeC)typeC.destroy();typeC=new Chart(document.getElementById('type'),{type:'doughnut',data:{labels:ts,datasets:[{data:vals,backgroundColor:ts.map(function(x,i){return PAL[i%PAL.length];})}]},options:{responsive:true,maintainAspectRatio:false,cutout:'58%',plugins:{legend:{position:'bottom',labels:{font:{size:11}}}}}});}
function locAgg(){var v=view();var m={};v.forEach(function(r){var k=r.L||'No location';if(!m[k])m[k]={loc:k,d:0,h:0,b:0,res:0};m[k].d+=r.d;m[k].h+=r.h;m[k].b+=r.b;m[k].res+=1;});var a=Object.keys(m).map(function(k){return m[k];});a.sort(function(x,y){return y[metric]-x[metric];});return a;}
function locTable(){document.getElementById('lt').textContent='Locations - most used (by '+(metric==='d'?'days':'hours')+')';document.querySelector('#loc tbody').innerHTML=locAgg().map(function(r,i){return '<tr><td class="num rankcell">'+(i+1)+'</td><td>'+r.loc+'</td><td class=num>'+r.d.toLocaleString()+'</td><td class=num>'+one(r.h)+'</td><td class=num>'+r.b.toLocaleString()+'</td><td class=num>'+r.res+'</td></tr>';}).join('');}
function tbl(){var v=view().slice().sort(function(a,b){var x=a[sk],y=b[sk];if(typeof x==='string')return x.localeCompare(y)*sd;return (x-y)*sd;});document.querySelector('#tbl tbody').innerHTML=v.map(function(r){return '<tr><td><span class=chip>'+r.t+'</span></td><td>'+r.n+'</td><td>'+r.L+'</td><td class=num>'+r.d.toLocaleString()+'</td><td class=num>'+one(r.h)+'</td><td class=num>'+r.b.toLocaleString()+'</td></tr>';}).join('');}
function render(){cards();rank();typeChart();locTable();tbl();document.getElementById('note').textContent=view().length?'':'No bookings in the selected date range.';}
function recompute(){compute();fillTypes();render();}
function setRange(a,b){from=a;to=b;document.getElementById('ds').value=a;document.getElementById('de').value=b;recompute();}
document.getElementById('ds').addEventListener('change',function(e){from=e.target.value||LOAD_S;recompute();});
document.getElementById('de').addEventListener('change',function(e){to=e.target.value||LOAD_E;recompute();});
document.getElementById('p13').addEventListener('click',function(){setRange(DEF_F,LOAD_E);});
document.getElementById('ppy').addEventListener('click',function(){setRange(PY_S,PY_E);});
document.getElementById('reset').addEventListener('click',function(){setRange(LOAD_S,LOAD_E);});
document.getElementById('tf').addEventListener('change',function(e){tf=(e.target.selectedIndex===0)?'':e.target.value;render();});
Array.prototype.forEach.call(document.querySelectorAll('#seg button'),function(b){b.addEventListener('click',function(){Array.prototype.forEach.call(document.querySelectorAll('#seg button'),function(x){x.classList.remove('on');});b.classList.add('on');metric=b.getAttribute('data-m');render();});});
Array.prototype.forEach.call(document.querySelectorAll('#tbl th'),function(th){th.addEventListener('click',function(){var k=th.getAttribute('data-s');if(!k)return;sd=(sk===k)?-sd:-1;sk=k;tbl();});});
recompute();
</script></body></html>`;
const fileName = 'Resource Utilization Dashboard ' + loadStart + ' to ' + endDay + '.html';
return [{ json: { fileName: fileName }, binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), fileName: fileName, mimeType: 'text/html', fileExtension: 'html' } } }];
